def transform(grid):
    from collections import Counter

    H, W = len(grid), len(grid[0])

    # Identify colors
    counter = Counter(cell for row in grid for cell in row)
    colors = sorted(counter.keys(), key=lambda x: counter[x], reverse=True)

    bg_color = colors[0]  # Most common - background
    other_colors = [c for c in colors if c != bg_color]

    # Noise color forms 3x3 blocks, target color is scattered
    noise_color = None
    target_color = None

    for c in other_colors:
        block_count = 0
        for r in range(H - 2):
            for col in range(W - 2):
                if all(grid[r+i][col+j] == c for i in range(3) for j in range(3)):
                    block_count += 1

        if block_count > 2:  # Has multiple 3x3 blocks
            noise_color = c
        else:
            target_color = c

    if noise_color is None:
        noise_color = other_colors[0]
    if target_color is None:
        target_color = other_colors[1] if len(other_colors) > 1 else other_colors[0]

    # Find unique noise block positions
    noise_blocks = []
    for r in range(H - 2):
        for col in range(W - 2):
            if all(grid[r+i][col+j] == noise_color for i in range(3) for j in range(3)):
                noise_blocks.append((r, col))

    # Get unique row and column indices
    unique_rows = sorted(set(p[0] for p in noise_blocks))
    unique_cols = sorted(set(p[1] for p in noise_blocks))

    # Output dimensions = number of unique positions
    out_rows = len(unique_rows) if unique_rows else 4
    out_cols = len(unique_cols) if unique_cols else 2

    output = [[bg_color]*out_cols for _ in range(out_rows)]

    # For each output cell, check target color in corresponding input region
    for r in range(out_rows):
        for c in range(out_cols):
            # Define region boundaries based on unique positions
            r_start = unique_rows[r] if unique_rows else 0
            r_end = unique_rows[min(r+1, len(unique_rows)-1)] if unique_rows else H
            if r_end >= H:
                r_end = H

            c_start = unique_cols[c] if unique_cols else 0
            c_end = unique_cols[min(c+1, len(unique_cols)-1)] if unique_cols else W
            if c_end >= W:
                c_end = W

            # If no unique positions, do full grid division
            if not unique_rows or not unique_cols:
                h_step = H / out_rows
                w_step = W / out_cols
                r_start = int(r * h_step)
                r_end = int((r + 1) * h_step)
                c_start = int(c * w_step)
                c_end = int((c + 1) * w_step)

            has_target = False
            for i in range(r_start, min(r_end, H)):
                for j in range(c_start, min(c_end, W)):
                    if grid[i][j] == target_color:
                        has_target = True
                        break
                if has_target:
                    break

            if has_target:
                output[r][c] = target_color

    return output
